/* Shared PC/mobile discovery. Examples remain clearly separate from live accounts. */
'use strict';
const shelfGroups=[
 {id:'tech',number:'000',symbol:'🎮',name:'게임·컴퓨터',hint:'게임 제작, 코딩, 앱 개발과 AI가 궁금하다면',codes:['000']},
 {id:'create',number:'100',symbol:'🎨',name:'그림·영상·음악',hint:'그림, 디자인, 영상, 음악과 글을 만드는 이야기',codes:['400','500']},
 {id:'science',number:'200',symbol:'🔬',name:'과학·만들기',hint:'실험, 연구, 로봇과 건축처럼 직접 탐구하고 만드는 이야기',codes:['100','800']},
 {id:'care',number:'300',symbol:'🩺',name:'교육·건강·돌봄',hint:'가르치기, 의료, 간호, 상담과 복지에 관한 경험',codes:['200','300']},
 {id:'society',number:'400',symbol:'🌱',name:'사회·환경',hint:'법, 경찰, 국제교류, 환경과 우리 동네가 궁금하다면',codes:['700','900']},
 {id:'business',number:'500',symbol:'💡',name:'돈·경제·창업',hint:'경제, 마케팅, 가게 운영과 작은 창업의 경험',codes:['600']}
];
const openShelfGroup={id:'open',symbol:'🌿',name:'아직 모르겠어요',hint:'분야를 정하지 않아도 이야기부터 시작해요.',codes:['open']};
function fieldGroup(value){return shelfGroups.find(g=>g.id===value||g.name===value||g.codes.includes(value)||g.codes.some(code=>classifications.find(c=>c.code===code)?.name===normalizeField(value)))||(['open','분야 탐색 중','아직 탐색 중','아직 모르겠어요'].includes(value)?openShelfGroup:null)}
function catalogClassCode(category){return fieldGroup(category)?.codes[0]||'open'}
const previousClassificationOf=classificationOf;
classificationOf=b=>{const c=previousClassificationOf(b);if(c.code!=='open')return c;return classifications.find(x=>x.code===catalogClassCode(b.category))||c};
categories.splice(0,categories.length,'전체',...shelfGroups.map(g=>g.name),openShelfGroup.name);
let discovery={text:'',group:'all',concern:'전체',school:'전체',department:'전체',scope:'books',browse:false,order:'recent'};
const lifeExamples={
 b1:{title:'어린 왕자',why:'익숙한 것도 다르게 바라보는 마음을 배웠어요.'},
 b2:{title:'모모',why:'남의 속도보다 내 시간을 살펴보게 된 책이에요.'},
 b3:{title:'데미안',why:'정해진 길 밖에서 내 질문을 찾는 이야기가 남았어요.'},
 b4:{title:'아주 작은 습관의 힘',why:'작게 시작하고 이어가는 연습을 하게 됐어요.'},
 b5:{title:'월든',why:'내가 사는 곳과 일상을 새롭게 보게 됐어요.'},
 b6:{title:'코스모스',why:'음악과 과학 사이에도 연결이 있다는 호기심이 생겼어요.'}
};
const extraQuestions=[
 {id:'q-demo-3',title:'게임을 좋아하면 어떤 일을 해볼 수 있을까요?',body:'직업 이름은 잘 모르지만 직접 무언가 만들어보고 싶어요.',concern:'프로젝트 시작',field:'IT·디지털',author:'도토리 · 예시',example:true,answers:[{id:'a-demo-3',author:'지안',bookId:'b3',example:true,body:'처음에는 내가 즐기는 게임의 작은 규칙 하나를 만들어보세요. 무엇을 만드는 과정이 재미있는지 살피는 것도 좋은 시작이에요.'}]},
 {id:'q-demo-4',title:'그림은 좋아하는데 전공으로 선택해도 될까요?',body:'잘하는 친구들과 비교하면 자신이 없어요. 좋아하는 마음에서 출발한 경험이 궁금해요.',concern:'좋아하는 일',field:'예술·디자인',author:'연두 · 예시',example:true,answers:[{id:'a-demo-4',author:'서윤',bookId:'b1',example:true,body:'저도 비교하며 망설였어요. 작은 포스터를 부탁받아 만들어보며 어떤 과정이 즐거운지 알아갔어요. 제 책에서 첫 시도를 읽어보세요.'}]},
 {id:'q-demo-5',title:'계획을 세워도 자꾸 미뤄요. 어디서 시작할까요?',body:'많이 공부하는 것보다 꾸준히 시작하는 방법이 궁금해요.',concern:'공부 방법',field:'교육·학습',author:'새벽 · 예시',example:true,answers:[{id:'a-demo-5',author:'하람',bookId:'b4',example:true,body:'저는 하루 삼십 분처럼 지킬 수 있는 약속부터 시작했어요. 누군가와 오늘 이해한 한 가지를 나누는 것도 도움이 됐어요.'}]},
 ...catalogQuestions
];
for(const q of extraQuestions)if(!state.questions.some(x=>x.id===q.id))state.questions.push(q);
const baseQuestionsVisible=questionsVisible;
questionsVisible=()=>[...baseQuestionsVisible(),...extraQuestions.filter(q=>!state.questions.some(x=>x.id===q.id)&&!state.hiddenQuestions.includes(q.id))];
const plain=v=>String(v||'').toLowerCase().replace(/\s+/g,'');
function groupOf(b){return fieldGroup(b.fieldGroup)||fieldGroup(classificationOf(b).code)||fieldGroup(b.category)||openShelfGroup}
for(const b of books)if(mentorExamples[b.id])mentorExamples[b.id].interests=groupOf(b).name;
score=b=>state.interests.some(value=>fieldGroup(value)?.id===groupOf(b).id)?10:0;
reason=b=>score(b)>0?`${groupOf(b).name}에 관심 있는 나에게`:'새로운 관심사를 발견할 수 있는 이야기';
const previousCover=cover;
cover=b=>previousCover(b).replace(`<span>${classificationOf(b).code}</span>`,`<span>${groupOf(b).symbol}</span>`);
const previousCards=cards;
cards=(items,reasons=false)=>{let html=previousCards(items,reasons);for(const b of items)html=html.replaceAll(`${classificationOf(b).code} ${esc(classificationOf(b).name)}`,esc(groupOf(b).name));return html};
spine=(b,j)=>{const g=groupOf(b),saved=state.saved.includes(b.id);return `<article class="shelved-book ${bookRentals(b.id).length?'has-rental':''}" style="--book-height:${[222,238,214,230][j%4]}px">${rentalBadge(b.id,true)}<button class="book-spine cover-${b.color}" data-action="read" data-id="${b.id}" aria-label="${esc(g.name+', '+b.title.replaceAll('\n',' ')+', '+b.name+'의 사람책 읽기')}"><span class="spine-bands" aria-hidden="true"></span><span class="spine-title">${esc(b.title.replaceAll('\n',' '))}</span><span class="spine-author">${esc(b.name)} · ${b.ownerUid?'승인 멘토':'가상 예시'}</span><span class="spine-label"><strong>${g.symbol}</strong><span>${esc(g.name)}</span></span></button><button class="shelf-bookmark ${saved?'saved':''}" data-action="save" data-id="${b.id}" aria-label="${esc(b.name)}의 책 ${saved?'책장에서 꺼내기':'책장에 담기'}" aria-pressed="${saved}">${icon('book')}</button><button class="shelf-topic" data-action="group-select" data-value="${g.id}" aria-label="${esc(g.name)} 서가 보기">${g.symbol}</button></article>`};
function matchText(values){return !discovery.text||plain(values.join(' ')).includes(plain(discovery.text))}
function discoverBooks(){return allBooks().filter(b=>!state.blocked.includes(b.id)).filter(b=>{const p=mentorInfo(b);return (discovery.group==='all'||groupOf(b).id===discovery.group)&&(discovery.concern==='전체'||(p.concerns||[]).includes(discovery.concern))&&(discovery.school==='전체'||p.school===discovery.school)&&(discovery.department==='전체'||p.department===discovery.department)&&matchText([b.title,b.name,b.help,b.quote,b.category,b.affiliation,groupOf(b).name,...b.tags,...Object.values(p).flat()])})}
function questionGroups(q){if(q.field)return [fieldGroup(q.field)?.id||'open'];const ids=(q.answers||[]).map(a=>getBook(a.bookId)).filter(Boolean).map(b=>groupOf(b).id);return ids.length?ids:['open']}
function discoverQuestions(){return questionsVisible().filter(q=>(discovery.concern==='전체'||q.concern===discovery.concern)&&(discovery.group==='all'||questionGroups(q).includes(discovery.group))&&matchText([q.title,q.body,q.concern,fieldGroup(q.field)?.name||q.field||''])).filter(q=>discovery.order!=='unanswered'||(q.answerCount??q.answers?.length??0)===0).sort((a,b)=>(b.created||0)-(a.created||0))}
function searchTools(){const all=allBooks().filter(b=>!state.blocked.includes(b.id)),options=key=>[...new Set(all.map(b=>mentorInfo(b)[key]).filter(Boolean))];return `<section class="discovery-tools" aria-label="통합 검색과 필터"><form id="discovery-form" role="search"><label class="search">${icon('search')}<input name="search" aria-label="책과 질문 통합 검색" placeholder="궁금한 분야나 고민을 검색해요" value="${esc(discovery.text)}"><button type="submit" aria-label="통합 검색">${icon('arrow')}</button></label></form><div class="discovery-filter-row"><label>분야<select data-discovery="group" aria-label="관심 분야 필터"><option value="all">모든 분야</option>${shelfGroups.map(g=>`<option value="${g.id}" ${discovery.group===g.id?'selected':''}>${g.number} ${g.name}</option>`).join('')}<option value="open" ${discovery.group==='open'?'selected':''}>아직 모르겠어요</option></select></label><label>고민<select data-discovery="concern" aria-label="고민 필터"><option>전체</option>${concernOptions.map(c=>`<option ${discovery.concern===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><details class="more-filters" ${discovery.school!=='전체'||discovery.department!=='전체'?'open':''}><summary>학교·학과 (책)</summary><div>${[['school','학교'],['department','학과']].map(([key,label])=>`<label>${label}<select data-discovery="${key}" aria-label="${label} 필터"><option>전체</option>${options(key).map(v=>`<option ${discovery[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div></details><button class="text-link" data-action="discovery-reset">초기화</button><button class="catalog-info" data-action="classification-guide" aria-label="분류 기준 보기">${icon('library')}</button></div><div class="discovery-scopes" aria-label="검색 대상">${[['books','사람책'],['questions','질문']].map(([v,t])=>`<button data-action="discovery-scope" data-value="${v}" aria-pressed="${discovery.scope===v}" class="${discovery.scope===v?'active':''}">${t}</button>`).join('')}</div></section>`}
function recommendationScore(b){const p=mentorInfo(b);return (state.discoveryConcern&&(p.concerns||[]).includes(state.discoveryConcern)?20:0)+score(b)+(classificationOf(b).code==='open'&&!state.interests.length?2:0)}
function curatedShelf(){const list=allBooks().filter(b=>!state.blocked.includes(b.id)).sort((a,b)=>recommendationScore(b)-recommendationScore(a)).slice(0,3);return `<section class="curated-section"><div class="section-line"><div><span class="eyebrow">CURATED FOR YOU</span><h2>추천도서</h2></div><button class="text-link" data-action="interests">관심사 바꾸기</button></div><div class="concern-picks" aria-label="추천받을 고민">${['진로 고민','전공 탐색','공부 방법','좋아하는 일'].map(v=>`<button data-action="curation-concern" data-value="${v}" class="${state.discoveryConcern===v?'active':''}" aria-pressed="${state.discoveryConcern===v}">${esc(v)}</button>`).join('')}</div>${list.length?bookshelves(list,true):'<p>숨긴 책을 해제하면 추천을 볼 수 있어요.</p>'}</section>`}
function compactQuestionCards(list){return `<div class="question-discovery-grid">${list.map(q=>`<article class="discovery-question"><button class="question-open" data-action="open-question" data-id="${q.id}"><span class="question-tag">${esc(q.concern)}${q.example?'<small>예시</small>':''}</span><h3>${esc(q.title)}</h3><p>${esc(q.body)}</p><span class="question-stats">답변 ${(q.example?(q.answers||[]).length:(q.answerCount??q.answers?.length??0))} · ${q.created?new Date(q.created).toLocaleDateString('ko-KR'):'예시 질문'}</span></button><button class="question-save ${state.savedQuestions?.includes(q.id)?'saved':''}" data-action="save-question" data-id="${q.id}" aria-pressed="${!!state.savedQuestions?.includes(q.id)}" aria-label="질문 ${state.savedQuestions?.includes(q.id)?'저장 취소':'저장'}">${icon('book')}</button></article>`).join('')||'<p class="no-results">맞는 질문이 아직 없어요. 다른 필터를 고르거나 질문을 남겨보세요.</p>'}</div>`}
function discoveryResults(){const active=discovery.text||discovery.group!=='all'||discovery.concern!=='전체'||discovery.school!=='전체'||discovery.department!=='전체'||discovery.browse;const bs=discoverBooks(),qs=discoverQuestions();return `${discovery.scope!=='questions'?active?`<section><div class="section-line"><h2>찾은 사람책 <small>${bs.length}권</small></h2><button class="text-link" data-action="discovery-home">추천으로</button></div>${bs.length?bookshelves(bs):'<p class="no-results">이 조건의 책이 아직 없어요. 필터를 넓혀볼까요?</p>'}</section>`:curatedShelf():''}${discovery.scope!=='books'?`<section class="question-discovery-section"><div class="section-line"><div><span class="eyebrow">QUESTIONS WE SHARE</span><h2>다른 친구들은 무엇이 궁금할까?</h2></div><button class="text-link" data-action="ask-question">질문 남기기 ${icon('pen')}</button></div>${compactQuestionCards(active||discovery.scope==='questions'?qs:qs.slice(0,3))}<a class="community-more" href="#community">질문 모아보기 ${icon('arrow')}</a></section>`:''}${!active&&discovery.scope!=='questions'?'<button class="btn full all-shelves" data-action="browse-all">전체 사람책 서가 보기</button>':''}`}
library=()=>`<section class="discovery-welcome"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>궁금한 마음이,<br> 다음 책을 고르는 순간.</h1><p>한 사람의 경험에서 나의 힌트를 찾아요.</p></section>${searchTools()}<div id="discovery-results">${discoveryResults()}</div>`;
mobileLibrary=library;
libraryResults=discoveryResults;
bookshelves=(list,curated=false)=>{const groups=curated?[{symbol:'📚',name:'오늘의 추천 서가',id:'curated',hint:'마음이 가는 책을 꺼내보세요.'}]:[...shelfGroups,openShelfGroup];return `<div class="library-bookcase ${curated?'curated-bookcase':''}">${groups.map((g,i)=>{const items=curated?list:list.filter(b=>groupOf(b).id===g.id);return items.length?`<section class="shelf-bay"><div class="shelf-heading"><span class="shelf-range">${g.symbol}</span><h3>${esc(g.name)}</h3><span class="shelf-count">${items.length}권</span><div class="shelf-motion-controls" aria-label="책 슬라이드"><button data-shelf-step="-1" aria-label="${g.name} 이전 책">${icon('arrow')}</button><button data-shelf-step="1" aria-label="${g.name} 다음 책">${icon('arrow')}</button></div></div><div class="shelf-interior"><div class="shelf-scroll" tabindex="0" role="group" aria-label="${g.name} 좌우로 넘기기"><div class="standing-books">${items.map(spine).join('')}<div class="bookend" aria-hidden="true"></div></div></div><div class="shelf-poem" aria-hidden="true"><p>${esc(g.hint)}</p></div></div><div class="wood-ledge"><span>WONJU STORY LIBRARY</span><span>천천히, 한 권씩</span></div></section>`:''}).join('')}</div>`};
classificationGuide=()=>openModal('어떤 이야기가 궁금한가요?',`<div class="modal-body"><p>우리 앱의 여섯 분야에 000~500 분류번호를 붙였어요. 고민은 별도의 고민 필터에서 골라요.</p><div class="classification-table">${[...shelfGroups,openShelfGroup].map(g=>`<button data-action="group-select" data-value="${g.id}"><b>${g.number||g.symbol}</b><span><strong>${g.name}</strong><small>${g.hint}</small></span>${icon('arrow')}</button>`).join('')}</div><p class="pill-note">책의 대표 경험을 기준으로 분류했어요. 관심이 여러 개여도 괜찮아요. 아직 분야를 고르기 어렵다면 ‘아직 모르겠어요’에서 시작해요.</p></div>`);
const baseMentorPanel=mentorProfilePanel;
mentorProfilePanel=b=>{const p=mentorInfo(b),life={...(lifeExamples[b.id]||{}),...(p.lifeBook?{title:p.lifeBook,why:p.lifeReason||''}:{})};return `<section class="life-book"><span class="eyebrow">OUR FIRST CONVERSATION</span><h3>나를 소개하는 인생책</h3><strong>${esc(life.title||'아직 고르는 중이에요')}</strong><p>${esc(life.why||'첫 만남에서 마음에 남은 책을 함께 이야기해요.')}</p>${b.id.startsWith('b')?'<small>가상 멘토의 소개 예시</small>':''}</section>${baseMentorPanel(b)}${availabilityPanel(b)}`};
function availabilityPanel(b){const busy=bookRentals(b.id).find(m=>rentalRange(m).start<=dayISO()),p=mentorInfo(b);return `<section class="availability-panel"><div><h3>함께 이야기할 시간</h3><span>온라인 · Teams · 20~30분</span></div>${busy?`<strong class="busy-until">${formatDay(rentalRange(busy).end)}까지 대여중</strong>`:''}<p>${esc(p.availability||'화·목 저녁 7시 / 토요일 오전 10시 (예시)')}</p><small>${b.id.startsWith('b')?'예시 시간이며 실제 예약은 받지 않아요.':'서로 수락한 뒤 운영자가 미팅을 안내해요.'}</small></section>`}
const baseReadBook=readBook;
readBook=id=>{baseReadBook(id);const b=getBook(id);if(!b)return;const busy=bookRentals(id).some(m=>rentalRange(m).start<=dayISO());$('.reader-portrait', $('#dialog'))?.classList.toggle('on-loan',busy);const questions=questionsVisible().filter(q=>(q.answers||[]).some(a=>a.bookId===id));if(questions.length)$('.reader-actions')?.insertAdjacentHTML('beforebegin',`<section class="book-questions"><h3>이 멘토가 함께 생각한 질문</h3>${questions.map(q=>`<button data-action="open-question" data-id="${q.id}">${esc(q.title)} ${icon('arrow')}</button>`).join('')}</section>`)};
communityPage=()=>`<section class="discovery-welcome"><span class="eyebrow">OUR QUESTION SHELF</span><h1>혼자 궁금해하지 않아도 돼요.</h1><p>질문을 읽고, 경험을 듣고, 다음 책을 만나요.</p></section><div class="community-heading"><div class="segmented"><button data-action="community-tab" data-value="questions" class="${communityTab==='questions'?'active':''}">공개 질문</button><button data-action="community-tab" data-value="saved" class="${communityTab==='saved'?'active':''}">저장한 질문</button><button data-action="community-tab" data-value="chats" class="${communityTab==='chats'?'active':''}">1:1 대화</button></div><button class="btn primary" data-action="ask-question">질문 남기기</button></div>${communityTab==='chats'?conversationList():`${questionSearchTools()}<div class="section-line"><h2>${communityTab==='saved'?'다시 읽고 싶은 질문':'함께 나누는 질문'}</h2><select aria-label="질문 정렬" data-discovery="order"><option value="recent" ${discovery.order==='recent'?'selected':''}>최근 질문</option><option value="unanswered" ${discovery.order==='unanswered'?'selected':''}>답변 기다리는 질문</option></select></div>${compactQuestionCards(discoverQuestions().filter(q=>communityTab!=='saved'||state.savedQuestions?.includes(q.id)))}`}`;
function questionSearchTools(){return searchTools().replace(/<div class="discovery-scopes"[\s\S]*?<\/div>/,'').replace(/<details class="more-filters"[\s\S]*?<\/details>/,'')}
const baseAskQuestion=askQuestion;
askQuestion=()=>{baseAskQuestion();if(!$('#question-form'))return;$('#question-error').insertAdjacentHTML('beforebegin',`<div class="similar-questions" id="similar-questions"><strong>먼저 읽어볼 질문</strong><div>${questionsVisible().slice(0,2).map(q=>`<button type="button" data-action="open-question" data-id="${q.id}">${esc(q.title)}</button>`).join('')}</div><small>비슷한 단어와 고민 태그로 찾은 질문이에요.</small></div>`);};
const baseProfileForm=mentorProfileForm;
mentorProfileForm=p=>baseProfileForm(p).replace('<p class="form-error"',`<label class="field"><span>나의 인생책</span><input name="lifeBook" maxlength="80" value="${esc(p.lifeBook||'')}" placeholder="책 제목"></label><label class="field"><span>이 책으로 시작하고 싶은 이야기</span><textarea name="lifeReason" maxlength="400">${esc(p.lifeReason||'')}</textarea></label><label class="field"><span>가능한 시간대</span><input name="availability" maxlength="120" value="${esc(p.availability||'')}" placeholder="예: 화·목 저녁 7시, 20~30분"></label><p class="form-error"`);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id,value}=el.dataset;if(action==='curation-concern'){state.discoveryConcern=state.discoveryConcern===value?'':value;persist();render()}if(action==='browse-all'){discovery.browse=true;render()}if(action==='discovery-home'){discovery.browse=false;discovery.text='';discovery.group='all';discovery.concern='전체';discovery.school='전체';discovery.department='전체';render()}if(action==='discovery-reset'){discovery={...discovery,text:'',group:'all',concern:'전체',school:'전체',department:'전체',browse:false};render()}if(action==='discovery-scope'){discovery.scope=value;render()}if(action==='group-select'){discovery.group=value;closeModal();if(page==='library')render();else location.hash='library'}if(action==='save-question'){state.savedQuestions=state.savedQuestions||[];state.savedQuestions=state.savedQuestions.includes(id)?state.savedQuestions.filter(x=>x!==id):[...state.savedQuestions,id];persist();render();toast('질문 책갈피를 바꿨어요.')}});
document.addEventListener('change',e=>{if(e.target.dataset.discovery){discovery[e.target.dataset.discovery]=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='discovery-form'){e.preventDefault();discovery.text=new FormData(e.target).get('search').trim();render()}});
document.addEventListener('input',e=>{if(!e.target.closest('#question-form'))return;const f=$('#question-form'),d=new FormData(f),words=plain(d.get('title')).split(/[?,.]/).filter(Boolean),list=questionsVisible().map(q=>({q,s:(q.concern===d.get('concern')?1:0)+words.filter(w=>plain(q.title+q.body).includes(w)).length*3})).sort((a,b)=>b.s-a.s).slice(0,2);$('#similar-questions div').innerHTML=list.map(({q})=>`<button type="button" data-action="open-question" data-id="${q.id}">${esc(q.title)}</button>`).join('')});
render();
